137	#[derive(Debug, PartialEq, Eq, Clone)]
138	enum ParseState<'a> {
139	    /// Parsing a value done, there is no state to record.
140	    ValueDone,
141	
142	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
143	    Pos((usize, usize)),
144	
145	    /// Parsing a optional flag argument
146	    Opt((&'a clap::Arg, usize)),
147	}
