149	fn complete_arg(
150	    arg: &clap_lex::ParsedArg<'_>,
151	    cmd: &clap::Command,
152	    current_dir: Option<&std::path::Path>,
153	    pos_index: usize,
154	    is_escaped: bool,
155	    state: ParseState<'_>,
156	    used_args: &[clap::Id],
157	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
158	    debug!(
159	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
160	        arg,
161	        cmd.get_name(),
162	        current_dir,
163	        pos_index,
164	        state
165	    );
166	    let mut completions = Vec::<CompletionCandidate>::new();
167	
168	    match state {
169	        ParseState::ValueDone => {
170	            if !is_escaped {
171	                if let Ok(value) = arg.to_value() {
172	                    completions.extend(complete_subcommand(value, cmd));
173	                }
174	            }
175	
176	            if let Some(positional) = cmd
177	                .get_positionals()
178	                .find(|p| p.get_index() == Some(pos_index))
179	            {
180	                completions.extend(complete_arg_value(
181	                    arg.to_value(),
182	                    positional,
183	                    current_dir,
184	                    0,
185	                ));
186	            }
187	            if !is_escaped {
188	                completions.extend(complete_option(arg, cmd, current_dir));
189	            }
190	        }
191	        ParseState::Pos((_, num_arg)) => {
192	            if let Some(positional) = cmd
193	                .get_positionals()
194	                .find(|p| p.get_index() == Some(pos_index))
195	            {
196	                completions.extend(complete_arg_value(
197	                    arg.to_value(),
198	                    positional,
199	                    current_dir,
200	                    num_arg.saturating_sub(1),
201	                ));
202	                if !is_escaped
203	                    && positional
204	                        .get_num_args()
205	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
206	                {
207	                    completions.extend(complete_option(arg, cmd, current_dir));
208	                }
209	            }
210	        }
211	        ParseState::Opt((opt, count)) => {
212	            completions.extend(complete_arg_value(
213	                arg.to_value(),
214	                opt,
215	                current_dir,
216	                count.saturating_sub(1),
217	            ));
218	            let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
219	            if count > min && can_switch_to_other_arg(opt, arg) {
220	                // The option's required values are satisfied and this word
221	                // would be parsed as a new flag rather than another value, so
222	                // also complete it as a positional, flag, option or subcommand.
223	                completions.extend(complete_arg(
224	                    arg,
225	                    cmd,
226	                    current_dir,
227	                    pos_index,
228	                    is_escaped,
229	                    ParseState::ValueDone,
230	                    used_args,
231	                )?);
232	            }
233	        }
234	    }
235	    filter_conflicting_candidates(&mut completions, cmd, used_args);
236	    if completions.iter().any(|a| !a.is_hide_set()) {
237	        completions.retain(|a| !a.is_hide_set());
238	    }
239	    let mut seen_ids = std::collections::HashSet::new();
240	    completions.retain(move |a| {
241	        if let Some(id) = a.get_id().cloned() {
242	            seen_ids.insert(id)
243	        } else {
244	            true
245	        }
246	    });
247	
248	    let mut tags = Vec::new();
249	    for candidate in &completions {
250	        let tag = candidate.get_tag().cloned();
251	        if !tags.contains(&tag) {
252	            tags.push(tag);
253	        }
254	    }
255	    completions.sort_by_key(|c| {
256	        (
257	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
258	            c.get_display_order(),
259	        )
260	    });
261	
262	    Ok(completions)
263	}
