464	fn complete_value_candidates(
465	    value: &OsStr,
466	    completer: &dyn ValueCandidates,
467	) -> Vec<CompletionCandidate> {
468	    debug!("complete_value_candidates: value={value:?}");
469	
470	    let mut values = completer.candidates();
471	    values.retain(|comp| comp.get_value().starts_with(&value.to_string_lossy()));
472	    values
473	}
