520	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
521	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
522	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
523	    debug!("longs: name={}", p.get_name());
524	
525	    p.get_arguments()
526	        .filter_map(|a| {
527	            a.get_long_and_visible_aliases().map(|longs| {
528	                longs
529	                    .into_iter()
530	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
531	            })
532	        })
533	        .flatten()
534	        .collect()
535	}
536	
537	/// Gets all the long hidden aliases and flags of a [`clap::Command`].
538	fn hidden_longs_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
539	    debug!("longs: name={}", p.get_name());
540	
541	    p.get_arguments()
542	        .filter_map(|a| {
543	            a.get_aliases().map(|longs| {
544	                longs.into_iter().map(|s| {
545	                    populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a).hide(true)
546	                })
547	            })
548	        })
549	        .flatten()
550	        .collect()
551	}
