599	/// Gets subcommands of [`clap::Command`] in the form of `("name", "bin_name")`.
600	///
601	/// Subcommand `rustup toolchain install` would be converted to
602	/// `("install", "rustup toolchain install")`.
603	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
604	    debug!("subcommands: name={}", p.get_name());
605	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
606	    p.get_subcommands()
607	        .flat_map(|sc| {
608	            sc.get_name_and_visible_aliases()
609	                .into_iter()
610	                .map(|s| populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc))
611	                .chain(sc.get_aliases().map(|s| {
612	                    populate_command_candidate(CompletionCandidate::new(s.to_owned()), p, sc)
613	                        .hide(true)
614	                }))
615	        })
616	        .collect()
617	}
618	
619	fn populate_command_candidate(
620	    candidate: CompletionCandidate,
621	    cmd: &clap::Command,
622	    subcommand: &clap::Command,
623	) -> CompletionCandidate {
624	    candidate
625	        .help(subcommand.get_about().cloned())
626	        .id(Some(format!("command::{}", subcommand.get_name())))
627	        .tag(Some(
628	            cmd.get_subcommand_help_heading()
629	                .unwrap_or("Commands")
630	                .to_owned()
631	                .into(),
632	        ))
633	        .display_order(Some(subcommand.get_display_order()))
634	        .hide(subcommand.is_hide_set())
635	}
636	
637	/// Parse the short flags and find the first `takes_values` option.
638	///
639	/// Returns the raw leading flags, every matched argument, the first
640	/// `takes_values` option (if any), and the remaining unparsed flags.
641	fn parse_shortflags<'c, 's>(
642	    cmd: &'c clap::Command,
643	    mut short: clap_lex::ShortFlags<'s>,
644	) -> (
645	    String,
646	    Vec<&'c clap::Arg>,
647	    Option<&'c clap::Arg>,
648	    clap_lex::ShortFlags<'s>,
649	) {
650	    let takes_value_opt;
651	    let mut matched_opts = Vec::new();
652	    let mut leading_flags = String::new();
653	    // Find the first takes_values option.
654	    loop {
655	        match short.next_flag() {
656	            Some(Ok(opt)) => {
657	                leading_flags.push(opt);
658	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
659	                if let Some(opt) = opt {
660	                    matched_opts.push(opt);
661	                }
662	                if opt
663	                    .map(|o| o.get_num_args().expect("built").takes_values())
664	                    .unwrap_or(false)
665	                {
666	                    takes_value_opt = opt;
667	                    break;
668	                }
669	            }
670	            Some(Err(_)) | None => {
671	                takes_value_opt = None;
672	                break;
673	            }
674	        }
675	    }
676	
677	    (leading_flags, matched_opts, takes_value_opt, short)
678	}
679	
680	/// Whether the argument can be addressed by the long flag `flag`,
681	/// including visible and hidden aliases.
682	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
683	    arg.get_long() == Some(flag)
684	        || arg
685	            .get_all_aliases()
686	            .is_some_and(|aliases| aliases.contains(&flag))
687	}
688	
689	/// Whether the argument can be addressed by the short flag `flag`,
690	/// including visible and hidden aliases.
691	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
692	    arg.get_short() == Some(flag)
693	        || arg
694	            .get_all_short_aliases()
695	            .is_some_and(|aliases| aliases.contains(&flag))
696	}
697	
698	/// Remove candidates for arguments that conflict with arguments already
699	/// present on the command line.
700	///
701	/// Conflicts only need to be declared on one of the two arguments; a
702	/// candidate is removed when either it or an already-used argument names
703	/// the other as a conflict. Anything that is not an argument candidate
704	/// (positional values, subcommands, custom candidates) is left untouched.
705	fn filter_conflicting_candidates(
706	    completions: &mut Vec<CompletionCandidate>,
707	    cmd: &clap::Command,
708	    used_args: &[clap::Id],
709	) {
710	    if used_args.is_empty() {
711	        return;
712	    }
713	    completions.retain(|candidate| {
714	        let Some(arg) = candidate
715	            .get_id()
716	            .and_then(|id| id.strip_prefix("arg::"))
717	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
718	        else {
719	            return true;
720	        };
721	        !used_args.iter().any(|used_id| {
722	            cmd.get_arguments()
723	                .find(|a| a.get_id() == used_id)
724	                .is_some_and(|used| args_conflict(cmd, arg, used))
725	        })
726	    });
727	}
728	
729	/// Whether `first` and `second` conflict, no matter which one declares it.
730	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
731	    cmd.get_arg_conflicts_with(first)
732	        .iter()
733	        .any(|c| c.get_id() == second.get_id())
734	        || cmd
735	            .get_arg_conflicts_with(second)
736	            .iter()
737	            .any(|c| c.get_id() == first.get_id())
738	}
739	
740	/// Parse the positional arguments. Return the new state and the new positional index.
741	fn parse_positional<'a>(
742	    cmd: &clap::Command,
743	    pos_index: usize,
744	    is_escaped: bool,
745	    state: ParseState<'a>,
746	) -> (ParseState<'a>, usize) {
747	    let pos_arg = cmd
748	        .get_positionals()
749	        .find(|p| p.get_index() == Some(pos_index));
750	    let num_args = pos_arg
751	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
752	        .unwrap_or(1);
753	
754	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
755	        if num_args > 1 {
756	            (ParseState::Pos((pos_index, 1)), pos_index)
757	        } else {
758	            if is_escaped {
759	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
760	            } else {
761	                (ParseState::ValueDone, pos_index + 1)
762	            }
763	        }
764	    };
765	    match state {
766	        ParseState::ValueDone => {
767	            update_state_with_new_positional(pos_index)
768	        },
769	        ParseState::Pos((prev_pos_index, num_arg)) => {
770	            if prev_pos_index == pos_index {
771	                if num_arg + 1 < num_args {
772	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
773	                } else {
774	                    if is_escaped {
775	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
776	                    } else {
777	                        (ParseState::ValueDone, pos_index + 1)
778	                    }
779	                }
780	            } else {
781	                update_state_with_new_positional(pos_index)
782	            }
783	        }
784	        ParseState::Opt(..) => unreachable!(
785	            "This branch won't be hit,
786	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
787	        ),
788	    }
789	}
790	
791	/// Parse optional flag argument. Return new state
792	fn parse_opt_value(opt: &clap::Arg, count: usize) -> ParseState<'_> {
793	    let range = opt.get_num_args().expect("built");
794	    let max = range.max_values();
795	    if count < max {
796	        ParseState::Opt((opt, count + 1))
797	    } else {
798	        ParseState::ValueDone
799	    }
800	}
801	
802	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
803	/// for, honoring the value delimiter.
804	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
805	    match (opt.get_value_delimiter(), value.to_str()) {
806	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
807	        _ => 1,
808	    }
809	}
810	
811	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
812	    cmd.get_positionals()
813	        .find(|a| a.get_index() == Some(pos_index))
814	        .map(|p| p.is_allow_hyphen_values_set())
815	        .unwrap_or(false)
816	}
817	
818	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
819	    let val = arg.to_value_os();
820	    if val.starts_with("-") {
821	        if let ParseState::Opt((opt, _)) = state {
822	            return opt.is_allow_hyphen_values_set();
823	        }
824	    }
825	
826	    false
827	}
828	
829	/// Whether a word can terminate a still-open multi-value option and start a
830	/// new argument instead, the way the parser would read it.
831	///
832	/// While an option still owes values, the parser greedily consumes every plain
833	/// word as one of its values; only flag-like words can switch to another
834	/// argument. An option that accepts hyphen values consumes those too.
835	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
836	    if arg.is_escape() {
837	        // `--` cancels every pending option unless its values may start with `--`.
838	        return !pending.is_allow_hyphen_values_set();
839	    }
840	    if !arg.to_value_os().starts_with("-") {
841	        // A plain word is always another value of the pending option.
842	        return false;
843	    }
844	    if pending.is_allow_hyphen_values_set() {
845	        return false;
846	    }
847	    // `-` is a stdio/value, not a flag.
848	    if arg.is_stdio() {
849	        return false;
850	    }
851	    // Both long and short flag styles can start a new argument; unknown flags
852	    // still switch (and error during parsing) rather than become option values.
853	    arg.to_long().is_some() || arg.to_short().is_some()
854	}
