#![cfg(feature = "unstable-dynamic")]

use clap::Command;
use clap_complete::engine::CompletionCandidate;

fn alias_tool_cmd() -> Command {
    Command::new("tool")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .disable_help_subcommand(true)
        .arg(clap::Arg::new("root-pos").value_parser(["config", "status"]))
        .subcommand(
            Command::new("run")
                .visible_alias("r")
                .alias("legacy-run")
                .about("Run a job")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .disable_help_subcommand(true)
                .arg(clap::Arg::new("run-pos").value_parser(["job", "log"]))
                .arg(
                    clap::Arg::new("env")
                        .long("env")
                        .value_parser(["dev", "prod"])
                        .help("Target environment"),
                )
                .subcommand(
                    Command::new("deploy")
                        .visible_alias("d")
                        .about("Deploy a plan")
                        .disable_help_flag(true)
                        .disable_version_flag(true)
                        .disable_help_subcommand(true)
                        .arg(clap::Arg::new("deploy-pos").value_parser(["plan", "force"]))
                        .arg(
                            clap::Arg::new("target")
                                .long("target")
                                .value_parser(["local", "remote"])
                                .help("Deploy target"),
                        ),
                ),
        )
        .subcommand(
            Command::new("inspect")
                .visible_alias("i")
                .about("Inspect state")
                .disable_help_flag(true)
                .disable_version_flag(true)
                .disable_help_subcommand(true),
        )
}

fn c(args: &[&str]) -> Vec<String> {
    let mut cmd = alias_tool_cmd();
    let args: Vec<std::ffi::OsString> = args.iter().map(std::ffi::OsString::from).collect();
    let arg_index = args.len() - 1;
    clap_complete::engine::complete(&mut cmd, args, arg_index, None)
        .map(|cs| {
            cs.into_iter()
                .map(|c| {
                    let v = c.get_value().to_string_lossy().into_owned();
                    match c.get_help() {
                        Some(h) => format!("{v}\t{h}"),
                        None => v,
                    }
                })
                .collect()
        })
        .unwrap_or_else(|e| vec![format!("ERR: {e}")])
}

#[test]
fn scratch() {
    let cases: &[&[&str]] = &[
        &["tool", ""],
        &["tool", "r"],
        &["tool", "i"],
        &["tool", "l"],
        &["tool", "run", ""],
        &["tool", "r", ""],
        &["tool", "legacy-run", ""],
        &["tool", "run", "deploy", ""],
        &["tool", "r", "d", ""],
        &["tool", "r", "--env", ""],
        &["tool", "r", "--env="],
        &["tool", "r", "--env", "p"],
        &["tool", "run", "--", ""],
        &["tool", "run", "--", "d"],
        &["tool", "run", "--", "--e"],
        &["tool", "--", ""],
        &["tool", "x"],
        &["tool", "run", "x"],
    ];
    for case in cases {
        println!("=== {case:?}");
        for line in c(case) {
            println!("  {line}");
        }
    }
}

